from collections import Counter,deque
def comps_of(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for y in range(H):
        for x in range(W):
            if g[y][x]!=bg and (y,x) not in seen:
                q=deque([(y,x)]); seen.add((y,x)); cs=[]
                while q:
                    a,b=q.popleft(); cs.append((a,b))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+dy,b+dx
                        if 0<=na<H and 0<=nb<W and g[na][nb]!=bg and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                out.append(cs)
    return out
def norm(cells):
    my=min(a for a,_ in cells); mx=min(b for _,b in cells)
    return tuple(sorted((a-my,b-mx) for a,b in cells))
def get_variants(cells):
    res=set(); cur=[(a,b) for a,b in cells]
    for _ in range(4):
        for rr in (cur,[(-a,b) for a,b in cur],[(a,-b) for a,b in cur]):
            res.add(norm(rr))
        cur=[(b,-a) for a,b in cur]
    return list(res)
def solve_pair(p, verbose=False):
    gi=G[f'Demo pair {p} input']; go_=G[f'Demo pair {p} output']
    bgv=Counter(v for r in gi for v in r).most_common(1)[0][0]
    tmpls=[c for c in comps_of(gi,bgv) if len(c)>1]
    marks=[c[0] for c in comps_of(gi,bgv) if len(c)==1]
    H,W=len(gi),len(gi[0])
    pred=[r[:] for r in gi]
    for m in marks:
        mc_=gi[m[0]][m[1]]
        cand=[T for T in tmpls if any(gi[a][b]==mc_ for a,b in T)]
        for T in cand:
            anchors=[(a,b) for a,b in T if gi[a][b]==mc_]
            for av in anchors:
                arel=(av[0]-min(x[0] for x in T), av[1]-min(x[1] for x in T))
                for V in get_variants(T):
                    va=[k for k,(a,b) in enumerate(V) if (a,b)==arel]
                    if not va: continue
                    vy,vx=V[va[0]]
                    tr=m[0]-vy; tx=m[1]-vx
                    ok=True
                    for a,b in V:
                        ny,trx=tr+a,tx+b
